(673, '_elementor_notifications_data', 'a:2:{s:7:\"timeout\";i:1791304797;s:5:\"value\";s:6045:\"[{\"id\":\"webinar-mcp-081026\",\"featured\":true,\"title\":\"Webinar on Thursday: Turn outdated sites into client offers\",\"description\":\"Join Roi and a very special guest - Imran, to see how they take an outdated site and rebuild it with the Elementor MCP in Codex. See the before and after, live edits by prompt and by hand, and how a few minutes of work can turn into your next client.\",\"topic\":\"Elementor MCP\",\"imageSrc\":\"https:\\/\\/assets.elementor.com\\/notifications\\/v1\\/images\\/webinar-081026.png\",\"link\":\"https:\\/\\/go.elementor.com\\/go-pro-notification-webinar-mcp-081026\\/\",\"readMoreText\":\"Learn More\"},{\"id\":\"4.3-elementor-mcp-new\",\"title\":\"Connect any AI tool to build and manage your site with the Elementor MCP\",\"description\":\"Claude, Codex, Cursor, and other compatible AI tools can now connect to your site and generate atomic pages, refine complex layouts, and control your design system from natural language prompts.\",\"topic\":\"Elementor MCP\",\"imageSrc\":\"https:\\/\\/assets.elementor.com\\/notifications\\/v1\\/images\\/4.3-mcp.png\",\"link\":\"https:\\/\\/go.elementor.com\\/go-pro-notification-4.3-mcp-page\\/\",\"readMoreText\":\"Learn More\",\"conditions\":[[{\"type\":\"plugin\",\"plugin\":\"elementor-pro\\/elementor-pro.php\"}]]},{\"id\":\"4.3-elementor-mcp-new\",\"title\":\"Connect any AI tool to build and manage your site with the Elementor MCP\",\"description\":\"Connect your site to Claude, Codex, Cursor, and other AI tools to generate pages, refine layouts, and control your design system. Upgrade to generate Forms, Popups, Dynamic Content and more\",\"topic\":\"Elementor MCP\",\"imageSrc\":\"https:\\/\\/assets.elementor.com\\/notifications\\/v1\\/images\\/4.3-mcp.png\",\"link\":\"https:\\/\\/go.elementor.com\\/go-pro-notification-4.3-mcp-page\\/\",\"readMoreText\":\"Learn More\",\"cta\":\"Upgrade\",\"ctaLink\":\"https:\\/\\/go.elementor.com\\/go-pro-notification-4.3-mcp-upgrade\\/\"},{\"id\":\"4.3-atomic-loop\",\"title\":\"Atomic Loop\",\"description\":\"Build dynamic, repeatable content layouts directly within the Atomic Editor. Display multiple posts, products, or custom content items using a single, customizable design template\",\"topic\":\"Atomic Editor\",\"imageSrc\":\"https:\\/\\/assets.elementor.com\\/notifications\\/v1\\/images\\/4.3-loop.png\",\"link\":\"https:\\/\\/go.elementor.com\\/go-pro-notification-4.3-atomic-loop-article\\/\",\"readMoreText\":\"Learn More\",\"cta\":\"Upgrade\",\"ctaLink\":\"https:\\/\\/go.elementor.com\\/go-pro-notification-4.3-loop\\/\",\"conditions\":[[{\"type\":\"plugin\",\"operator\":\"!=\",\"plugin\":\"elementor-pro\\/elementor-pro.php\"}]]},{\"id\":\"4.3-accordion-bg-video\",\"title\":\"New Atomic Loop, Accordion, and Background video\",\"description\":\"Build dynamic, repeatable content layouts, expandable content blocks, and engaging video backgrounds, with full atomic control over every part of each element.\",\"topic\":\"Atomic Editor\",\"imageSrc\":\"https:\\/\\/assets.elementor.com\\/notifications\\/v1\\/images\\/4.3-accordion.png\",\"link\":\"https:\\/\\/go.elementor.com\\/go-pro-notification-4.3-features\\/\",\"readMoreText\":\"Learn More\",\"conditions\":[[{\"type\":\"plugin\",\"plugin\":\"elementor-pro\\/elementor-pro.php\"}]]},{\"id\":\"4.3-accordion-bg-video\",\"title\":\"Atomic Accordion and Background video\",\"description\":\"Create expandable content blocks and engaging video backgrounds, with full atomic control over every part of each element\",\"topic\":\"Atomic Editor\",\"imageSrc\":\"https:\\/\\/assets.elementor.com\\/notifications\\/v1\\/images\\/4.3-accordion.png\",\"link\":\"https:\\/\\/go.elementor.com\\/go-pro-notification-4.3-features\\/\",\"readMoreText\":\"Learn More\"},{\"id\":\"angie-build-full-page\",\"title\":\"Generate full Elementor pages\",\"description\":\"Describe the layout you need and get a complete page, or generate individual sections like hero areas, feature blocks, and pricing tables one at a time. Every result can be matched to your site\'s existing styles or follow any new design instructions you give.\",\"topic\":\"Angie\",\"imageSrc\":\"https:\\/\\/assets.elementor.com\\/notifications\\/v1\\/images\\/angie-build-full-page.png\",\"link\":\"https:\\/\\/go.elementor.com\\/go-pro-notification-angie-build-with-prompts\\/\",\"readMoreText\":\"Learn More\"},{\"id\":\"4.3-angie-build-design-system\",\"title\":\"AI-Powered page & design system generation from within the Editor\",\"description\":\"Describe the layout you need and get a complete page, or generate individual sections like hero areas, feature blocks, and pricing tables one at a time. You can create a brand new design system, or use your site\\u2019s existing styles.\",\"topic\":\"Angie\",\"imageSrc\":\"https:\\/\\/assets.elementor.com\\/notifications\\/v1\\/images\\/angie-build-design-system.png\",\"link\":\"https:\\/\\/go.elementor.com\\/go-pro-notification-angie-build-with-prompts\\/\",\"readMoreText\":\"Learn More\"},{\"id\":\"4.3-angie-super-community\",\"title\":\"Discover and share in the Angie Community Library\",\"description\":\"Access a curated catalog of verified snippets and custom widgets created by fellow builders. Import them without consuming any credits, remix them to fit your vision, or showcase your own creations to the world.\",\"topic\":\"Angie\",\"imageSrc\":\"https:\\/\\/assets.elementor.com\\/notifications\\/v1\\/images\\/angie-community.png\",\"link\":\"https:\\/\\/go.elementor.com\\/go-pro-notification-angie-community\\/\",\"readMoreText\":\"Browse library\"},{\"id\":\"4.3-angie-super-admin\",\"title\":\"Super Admin Mode\",\"description\":\"Revolutionize your WordPress workflow with Super Admin Mode. Perform root-level WordPress operations through natural language - bulk post and product updates, PHP error diagnosis, and more.\",\"topic\":\"Angie\",\"imageSrc\":\"https:\\/\\/assets.elementor.com\\/notifications\\/v1\\/images\\/angie-super-admin.png\",\"link\":\"https:\\/\\/go.elementor.com\\/go-pro-notification-angie-super-admin\\/\",\"readMoreText\":\"Learn More\"},{\"id\":\"4.3-one-launch\",\"title\":\"Elementor One\",\"description\":\"The complete website building experience. All the tools to create, optimize, and manage websites, unified under one roof.\",\"topic\":\"Elementor One\",\"imageSrc\":\"https:\\/\\/assets.elementor.com\\/notifications\\/v1\\/images\\/one-launch.png\",\"cta\":\"Explore Elementor One\",\"ctaLink\":\"https:\\/\\/go.elementor.com\\/launch-whats-new\"}]\";}', 'off'),
(676, '_elementor_v4_promotions', 'a:2:{s:7:\"timeout\";i:1791265198;s:5:\"value\";s:3523:\"[{\"customCss\":{\"title\":\"Custom CSS\",\"content\":\"Add custom CSS to refine and enrich the appearance of any element on your site.\",\"ctaUrl\":\"https:\\/\\/go.elementor.com\\/go-pro-style-custom-css\\/\",\"image\":\"https:\\/\\/assets.elementor.com\\/packages\\/v1\\/images\\/custom_css_promotion.png\"},\"displayConditions\":{\"title\":\"Display conditions\",\"content\":\"Control when and where elements are shown across your site.\",\"ctaUrl\":\"https:\\/\\/go.elementor.com\\/go-pro-display-conditions-modal\\/\",\"image\":\"https:\\/\\/assets.elementor.com\\/packages\\/v1\\/images\\/display_conditions_promotion.png\"},\"attributes\":{\"title\":\"Attributes\",\"content\":\"Add custom attributes when you need deeper customization and better accessibility.\",\"ctaUrl\":\"https:\\/\\/go.elementor.com\\/go-pro-attributes-modal\\/\",\"image\":\"https:\\/\\/assets.elementor.com\\/packages\\/v1\\/images\\/attributes_promotion.png\"},\"Portfolio\":{\"title\":\"Portfolio\",\"content\":\"Upgrade to build dynamic portfolio grids featuring interactive category filtering and engaging hover effects designed to captivate your site visitors.\",\"image\":\"https:\\/\\/assets.elementor.com\\/packages\\/v1\\/images\\/Portfolio_promotion.png\"},\"Form\":{\"title\":\"Form\",\"content\":\"Upgrade to build advanced forms featuring custom fields, multi-step layouts, automated email notifications, and direct CRM integrations.\",\"image\":\"https:\\/\\/assets.elementor.com\\/packages\\/v1\\/images\\/Form_promotion.png\"},\"PriceList\":{\"title\":\"Price list\",\"content\":\"Upgrade to present items, descriptions, and pricing within a cohesive structure that aligned perfectly with your site.\",\"image\":\"https:\\/\\/assets.elementor.com\\/packages\\/v1\\/images\\/Price_list_promotion.png\"},\"PriceTable\":{\"title\":\"Price table\",\"content\":\"Upgrade to build pricing matrices featuring highlighted columns, interactive check mark lists, and integrated action buttons.\",\"image\":\"https:\\/\\/assets.elementor.com\\/packages\\/v1\\/images\\/Price_table_promotion.png\"},\"LoopGrid\":{\"title\":\"Loop Grid\",\"content\":\"Upgrade to connect custom layouts directly to your site database, seamlessly rendering dynamic content queries that engage your site visitors.\",\"image\":\"https:\\/\\/assets.elementor.com\\/packages\\/v1\\/images\\/Loop_grid_promotion.png\"},\"CallToAction\":{\"title\":\"Call to Action\",\"content\":\"Upgrade to build Call to Action blocks with image overlays, custom hover animations, and promotional layout control across your site.\",\"image\":\"https:\\/\\/assets.elementor.com\\/packages\\/v1\\/images\\/CTA_promotion.png\"},\"Template\":{\"title\":\"Template\",\"content\":\"Upgrade to embed saved templates that sync automatically across your entire site, preserving layout integrity and accelerating your production speed.\",\"image\":\"https:\\/\\/assets.elementor.com\\/packages\\/v1\\/images\\/Template_promotion.png\"},\"Gallery\":{\"title\":\"Gallery pro\",\"content\":\"Upgrade to build gallery with dynamic categorization and custom layout control across your site.\",\"image\":\"https:\\/\\/assets.elementor.com\\/packages\\/v1\\/images\\/Gallery_pro_promotion.png\"},\"MediaCarousel\":{\"title\":\"Media carousel\",\"content\":\"Upgrade to build advanced Media Carousel with dynamic video elements into your sliders to better engage your site visitors.\",\"image\":\"https:\\/\\/assets.elementor.com\\/packages\\/v1\\/images\\/Media_carousel_promotion.png\"},\"LoopCarousel\":{\"title\":\"Loop carousel\",\"content\":\"Upgrade to build advanced Loop Carousel with dynamic posts, custom layouts seamlessly to better engage your site visitors.\",\"image\":\"https:\\/\\/assets.elementor.com\\/packages\\/v1\\/images\\/Loop_carousel_promotion.png\"}}]\";}', 'off'),
